(()=>{
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches,clamp=(n,a,b)=>Math.min(b,Math.max(a,n));
const hero=document.querySelector('.office-hero'),cinema=document.querySelector('.cinema-section');
const shifts=[...document.querySelectorAll('.experience-card,.news-card,.culture-card,.department-card,.principle-grid>article,.timeline-item,.card,.gallery-item,.brand,.number-row')];shifts.forEach(e=>e.classList.add('scroll-shift'));
const depth=[...document.querySelectorAll('.photo-frame,.split img,.card .image img,.gallery-item img')];depth.forEach(e=>e.classList.add('scroll-photo-depth'));
function render(){if(reduce)return;const height=innerHeight,mobile=innerWidth<=800;if(hero){const r=hero.getBoundingClientRect();if(r.bottom>=0&&r.top<=height)hero.style.setProperty('--scene-progress',clamp(-r.top/(r.height*.85),0,1).toFixed(4))}shifts.forEach((e,i)=>{const r=e.getBoundingClientRect();if(r.bottom<-100||r.top>height+100)return;const entering=clamp((height-r.top)/(height*.8),0,1);e.style.setProperty('--scroll-rise',`${((1-entering)*(mobile?20:48)).toFixed(2)}px`);e.style.setProperty('--scroll-scale',(0.965+entering*.035).toFixed(4))});if(!mobile)depth.forEach(e=>{const r=e.getBoundingClientRect();if(r.bottom<0||r.top>height)return;const progress=clamp((height-r.top)/(height+r.height),0,1);e.style.setProperty('--photo-scale',(1.06-progress*.06).toFixed(4))});if(cinema){const r=cinema.getBoundingClientRect();if(r.bottom>=0&&r.top<=height){const entered=clamp((height-r.top)/(height*.8),0,1);cinema.style.setProperty('--cinema-inset',`${((1-entered)*7).toFixed(3)}%`);cinema.style.setProperty('--film-scale',(1.1-entered*.08).toFixed(4))}}}
let queued=false;function request(){if(queued||reduce)return;queued=true;requestAnimationFrame(()=>{render();queued=false})}addEventListener('scroll',request,{passive:true});addEventListener('resize',request);render();
const video=document.querySelector('#zorko-film');if(video){const toggle=document.querySelector('[data-film-toggle]'),sound=document.querySelector('[data-film-sound]'),error=document.querySelector('.cinema-error');let manualPause=false,visible=false;
function sync(){const playing=!video.paused;toggle.innerHTML=playing?'Pause film <span aria-hidden="true">Ⅱ</span>':'Play film <span aria-hidden="true">▶</span>';toggle.setAttribute('aria-label',playing?'Pause gallery film':'Play gallery film');sound.textContent=video.muted?'Sound off':'Sound on';sound.setAttribute('aria-pressed',String(!video.muted));sound.setAttribute('aria-label',video.muted?'Turn film sound on':'Turn film sound off')}
async function play(){try{await video.play();error.hidden=true;sync()}catch{sync()}}toggle.addEventListener('click',()=>{if(video.paused){manualPause=false;play()}else{manualPause=true;video.pause();sync()}});sound.addEventListener('click',()=>{video.muted=!video.muted;sync()});video.addEventListener('play',sync);video.addEventListener('pause',sync);video.addEventListener('volumechange',sync);video.addEventListener('error',()=>{error.hidden=false;sync()});video.querySelector('source').addEventListener('error',()=>{error.hidden=false});
const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible&&!reduce&&!navigator.connection?.saveData&&!manualPause&&!document.hidden)play();else if(!visible)video.pause()},{threshold:.25});observer.observe(video);document.addEventListener('visibilitychange',()=>{if(document.hidden)video.pause();else if(visible&&!reduce&&!manualPause&&!navigator.connection?.saveData)play()});sync();
}
})();
